// mailformat: Outlook Classic COM add-in. Adds Wrap / Quote / Unquote /
// Wrap + Quote buttons to the compose ribbon, operating on the selected text.
using System;
using System.Reflection;
using System.Runtime.InteropServices;
using Microsoft.Win32;

[assembly: AssemblyTitle("mailformat")]
// AssemblyVersion is generated by build.cmd (bin\Version.cs).
[assembly: ComVisible(false)]

namespace MailformatAddin
{
    // Declared here so no Office PIAs / Extensibility.dll are needed.
    // The `custom` parameter is a SAFEARRAY(VARIANT)*. The MarshalAs is required:
    // a bare System.Array marshals as an _Array interface pointer, which crashes the CLR.
    [ComImport, Guid("B65AD801-ABAF-11D0-BB8B-00A0C90F2744"), InterfaceType(ComInterfaceType.InterfaceIsDual)]
    public interface IDTExtensibility2
    {
        [DispId(1)] void OnConnection([MarshalAs(UnmanagedType.IDispatch)] object application, int connectMode,
                                      [MarshalAs(UnmanagedType.IDispatch)] object addInInst,
                                      [MarshalAs(UnmanagedType.SafeArray, SafeArraySubType = VarEnum.VT_VARIANT)] ref Array custom);
        [DispId(2)] void OnDisconnection(int removeMode,
                                         [MarshalAs(UnmanagedType.SafeArray, SafeArraySubType = VarEnum.VT_VARIANT)] ref Array custom);
        [DispId(3)] void OnAddInsUpdate([MarshalAs(UnmanagedType.SafeArray, SafeArraySubType = VarEnum.VT_VARIANT)] ref Array custom);
        [DispId(4)] void OnStartupComplete([MarshalAs(UnmanagedType.SafeArray, SafeArraySubType = VarEnum.VT_VARIANT)] ref Array custom);
        [DispId(5)] void OnBeginShutdown([MarshalAs(UnmanagedType.SafeArray, SafeArraySubType = VarEnum.VT_VARIANT)] ref Array custom);
    }

    [ComImport, Guid("000C0396-0000-0000-C000-000000000046"), InterfaceType(ComInterfaceType.InterfaceIsDual)]
    public interface IRibbonExtensibility
    {
        [DispId(1)] [return: MarshalAs(UnmanagedType.BStr)]
        string GetCustomUI([MarshalAs(UnmanagedType.BStr)] string ribbonId);
    }

    [ComVisible(true)]
    [Guid("6F3B5C2A-8E1D-4C7B-9A54-2D7E1F0B3A91")]
    [ProgId("mailformat.Connect")]
    [ClassInterface(ClassInterfaceType.AutoDispatch)]
    public class Connect : IDTExtensibility2, IRibbonExtensibility
    {
        const string SettingsKey = @"Software\mailformat";
        const int OlExplorer = 34, OlInspector = 35;

        const string Buttons =
            "<group id='mailformat' label='mailformat'>" +
            "<button id='wrap' tag='wrap' label='Wrap' keytip='YW' onAction='OnAction' screentip='Hard-wrap the selection to the text width'/>" +
            "<button id='quote' tag='quote' label='Quote' keytip='YQ' onAction='OnAction' screentip='Prefix every selected line with &gt;'/>" +
            "<button id='unquote' tag='unquote' label='Unquote' keytip='YU' onAction='OnAction' screentip='Remove one level of &gt; from the selection'/>" +
            "<button id='both' tag='both' label='Wrap + Quote' keytip='YB' onAction='OnAction' screentip='Wrap, then quote'/>" +
            "<button id='width' getLabel='GetWidthLabel' keytip='YT' onAction='OnSetWidth' screentip='Change the text width'/>" +
            "</group>";

        // Right-click menu of the mail editor (WordMail). Ids must be unique per customUI, so the mode is in tag.
        const string ContextMenu =
            "<contextMenus><contextMenu idMso='ContextMenuText'>" +
            "<menuSeparator id='mfSep'/>" +
            "<menu id='mfMenu' label='mailformat'>" +
            "<button id='cmWrap' tag='wrap' label='Wrap' onAction='OnAction'/>" +
            "<button id='cmQuote' tag='quote' label='Quote' onAction='OnAction'/>" +
            "<button id='cmUnquote' tag='unquote' label='Unquote' onAction='OnAction'/>" +
            "<button id='cmBoth' tag='both' label='Wrap + Quote' onAction='OnAction'/>" +
            "</menu></contextMenu></contextMenus>";

        const string Head = "<customUI xmlns='http://schemas.microsoft.com/office/2009/07/customui' onLoad='OnRibbonLoad'><ribbon>";

        object ribbon;
        object app;

        // The interface declaration's MarshalAs attributes govern marshalling for these.
        public void OnConnection(object application, int connectMode, object addInInst, ref Array custom) { app = application; }
        public void OnDisconnection(int removeMode, ref Array custom) { }
        public void OnAddInsUpdate(ref Array custom) { }
        public void OnStartupComplete(ref Array custom) { }
        public void OnBeginShutdown(ref Array custom) { }

        public string GetCustomUI(string ribbonId)
        {
            if (ribbonId == "Microsoft.Outlook.Mail.Compose")   // pop-out compose window
                return Head + "<tabs><tab idMso='TabNewMailMessage'>" + Buttons + "</tab></tabs></ribbon>" +
                       ContextMenu + "</customUI>";
            if (ribbonId == "Microsoft.Outlook.Explorer")       // inline reply in the reading pane
                return Head + "<contextualTabs><tabSet idMso='TabComposeTool'><tab idMso='TabMessage'>" + Buttons +
                       "</tab></tabSet></contextualTabs></ribbon>" + ContextMenu + "</customUI>";
            return null;
        }

        public void OnRibbonLoad(object ribbonUI) { ribbon = ribbonUI; }

        static int Width
        {
            get
            {
                using (var key = Registry.CurrentUser.OpenSubKey(SettingsKey))
                {
                    object v = key == null ? null : key.GetValue("Width");
                    return v is int && (int)v >= 10 ? (int)v : Mailformat.DefaultWidth;
                }
            }
            set
            {
                using (var key = Registry.CurrentUser.CreateSubKey(SettingsKey))
                    key.SetValue("Width", value, RegistryValueKind.DWord);
            }
        }

        public string GetWidthLabel(object control) { return "Width: " + Width; }

        public void OnSetWidth(object control)
        {
            string s = Microsoft.VisualBasic.Interaction.InputBox(
                "Text width (characters per line):", "mailformat", Width.ToString());
            int w;
            if (int.TryParse(s, out w) && w >= 10 && w <= 500)
            {
                Width = w;
                if (ribbon != null) ((dynamic)ribbon).Invalidate();
            }
        }

        public void OnAction(object control)
        {
            try
            {
                dynamic c = control;
                string mode = c.Tag;
                // Ribbon controls get the Inspector/Explorer as context; context-menu controls
                // may not, so fall back to the active window.
                dynamic window = null;
                int cls = 0;
                try { window = c.Context; cls = window.Class; } catch { cls = 0; }
                if (cls != OlInspector && cls != OlExplorer && app != null)
                {
                    window = ((dynamic)app).ActiveWindow();
                    cls = window == null ? 0 : (int)window.Class;
                }
                dynamic editor = cls == OlInspector ? window.WordEditor
                               : cls == OlExplorer ? window.ActiveInlineResponseWordEditor
                               : null;
                if (editor == null) return;
                dynamic word = editor.Application;
                dynamic sel = word.Selection;
                if ((int)sel.Start == (int)sel.End) return;   // nothing selected

                string text = sel.Text;
                if (string.IsNullOrEmpty(text)) return;

                // Word: \r = paragraph, \v = manual line break. Keep a trailing paragraph mark out of it.
                bool trailingCr = text.EndsWith("\r");
                if (trailingCr) text = text.Substring(0, text.Length - 1);
                text = text.Replace("\r\n", "\n").Replace('\r', '\n').Replace('\v', '\n');
                if (text.Length == 0) return;

                string output = Mailformat.Apply(mode, text, Width).Replace('\n', '\r');
                if (trailingCr) output += "\r";

                dynamic undo = null;
                try { undo = word.UndoRecord; undo.StartCustomRecord("mailformat"); } catch { undo = null; }
                try { sel.Text = output; }
                finally { if (undo != null) try { undo.EndCustomRecord(); } catch { } }
            }
            catch (Exception e)
            {
                System.Diagnostics.Trace.WriteLine("mailformat: " + e);
            }
        }
    }
}
